def is_palindrome(s: str) -> bool:
    left, right = 0, len(s) - 1
    while left < right:
        while left < right and not s[left].isalnum():
            left += 1
        while left < right and not s[right].isalnum():
            right -= 1
        if s[left].lower() != s[right].lower():
            return False
        left += 1
        right -= 1
    return True

def alpha_counts(s: str) -> List[int]:
    counts = [0] * 26
    for c in s:
        if c.isalpha():
            counts[char_index(c)] += 1
    return counts

def group_anagrams(words: List[str]) -> List[List[str]]:
    groups = defaultdict(list)
    for w in words:
        groups["".join(sorted(w))].append(w)
    return list(groups.values())

def two_sum_sorted(nums: List[int], target: int) -> Tuple[int, int]:
    left, right = 0, len(nums) - 1
    while left < right:
        total = nums[left] + nums[right]
        if total == target:
            return left, right
        if total < target:
            left += 1
        else:
            right -= 1
    return -1, -1

def two_sum(nums: List[int], target: int) -> Tuple[int, int]:
    seen: Dict[int, int] = {}
    for i, x in enumerate(nums):
        if target - x in seen:
            return seen[target - x], i
        seen[x] = i
    return -1, -1

def max_sum_window(nums: List[int], k: int) -> int:
    if k > len(nums):
        return 0
    window = sum(nums[:k])
    best = window
    for right in range(k, len(nums)):
        window += nums[right] - nums[right - k]
        best = max(best, window)
    return best

def prefix_sums(nums: List[int]) -> List[int]:
    pre = [0] * (len(nums) + 1)
    for i, x in enumerate(nums):
        pre[i + 1] = pre[i] + x
    return pre
    # one-liner alternative: [0] + list(accumulate(nums))

def kadane(nums: List[int]) -> int:
    best = current = nums[0]
    for x in nums[1:]:
        current = max(x, current + x)
        best = max(best, current)
    return best

def frequency(items) -> Dict:
    freq: Dict = {}
    for x in items:
        freq[x] = freq.get(x, 0) + 1
    return freq

def binary_search(nums: List[int], target: int) -> int:
    left, right = 0, len(nums) - 1
    while left <= right:                 # <= because left==right is a valid candidate
        mid = (left + right) // 2
        if nums[mid] == target:
            return mid
        if nums[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return -1

def lower_bound(nums: List[int], target: int) -> int:
    left, right = 0, len(nums)
    while left < right:                  # < because right is exclusive here
        mid = (left + right) // 2
        if nums[mid] < target:
            left = mid + 1
        else:
            right = mid
    return left

def binary_search_answer(lo: int, hi: int, feasible) -> int:
    while lo < hi:
        mid = (lo + hi) // 2
        if feasible(mid):
            hi = mid
        else:
            lo = mid + 1
    return lo

def valid_parentheses(s: str) -> bool:
    pairs = {")": "(", "]": "[", "}": "{"}
    stack: List[str] = []
    for c in s:
        if c in pairs:
            if not stack or stack.pop() != pairs[c]:
                return False
        else:
            stack.append(c)
    return not stack

def next_greater(nums: List[int]) -> List[int]:
    res = [-1] * len(nums)
    stack: List[int] = []
    for i, x in enumerate(nums):
        while stack and nums[stack[-1]] < x:
            res[stack.pop()] = x
        stack.append(i)
    return res

def k_largest(nums: List[int], k: int) -> List[int]:
    heap: List[int] = []
    for x in nums:
        heapq.heappush(heap, x)
        if len(heap) > k:
            heapq.heappop(heap)
    return sorted(heap, reverse=True)
    # shortcut: heapq.nlargest(k, nums)

class ListNode:
    def __init__(self, val=0, nxt=None):
        self.val = val
        self.next = nxt

    def __repr__(self):
        return f"{self.val} -> {self.next}" if self.next else str(self.val)

def to_pylist(head: Optional[ListNode]) -> List[int]:
    out = []
    while head:
        out.append(head.val)
        head = head.next
    return out

def reverse_list(head: Optional[ListNode]) -> Optional[ListNode]:
    prev = None
    while head:
        head.next, prev, head = prev, head, head.next
    return prev

def middle_node(head: Optional[ListNode]) -> Optional[ListNode]:
    slow = fast = head
    while fast and fast.next:
        slow = slow.next
        fast = fast.next.next
    return slow

def has_cycle(head: Optional[ListNode]) -> bool:
    slow = fast = head
    while fast and fast.next:
        slow = slow.next
        fast = fast.next.next
        if slow is fast:
            return True
    return False

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def inorder(root: Optional[TreeNode]) -> List[int]:
    out: List[int] = []

    def walk(node):
        if not node:
            return
        walk(node.left)
        out.append(node.val)
        walk(node.right)

    walk(root)
    return out

def inorder_iterative(root: Optional[TreeNode]) -> List[int]:
    out, stack, cur = [], [], root
    while cur or stack:
        while cur:
            stack.append(cur)
            cur = cur.left
        cur = stack.pop()
        out.append(cur.val)
        cur = cur.right
    return out

def level_order(root: Optional[TreeNode]) -> List[List[int]]:
    if not root:
        return []
    out, queue = [], deque([root])
    while queue:
        level = []
        for _ in range(len(queue)):
            node = queue.popleft()
            level.append(node.val)
            if node.left:
                queue.append(node.left)
            if node.right:
                queue.append(node.right)
        out.append(level)
    return out

def max_depth(root: Optional[TreeNode]) -> int:
    if not root:
        return 0
    return 1 + max(max_depth(root.left), max_depth(root.right))

def neighbors(r: int, c: int, grid: List[List], dirs=DIRS4):
    for dr, dc in dirs:
        nr, nc = r + dr, c + dc
        if in_bounds(nr, nc, grid):
            yield nr, nc

def bfs_grid(grid: List[List[str]], start: Tuple[int, int], passable="1") -> Set[Tuple[int, int]]:
    sr, sc = start
    if not in_bounds(sr, sc, grid) or grid[sr][sc] != passable:
        return set()
    visited = {start}
    queue = deque([start])
    while queue:
        r, c = queue.popleft()
        for nr, nc in neighbors(r, c, grid):
            if (nr, nc) not in visited and grid[nr][nc] == passable:
                visited.add((nr, nc))
                queue.append((nr, nc))
    return visited

def count_islands(grid: List[List[str]]) -> int:
    seen: Set[Tuple[int, int]] = set()
    count = 0
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == "1" and (r, c) not in seen:
                seen |= bfs_grid(grid, (r, c))
                count += 1
    return count

def build_graph(edges: List[Tuple[int, int]], directed=False) -> Dict[int, List[int]]:
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        if not directed:
            graph[v].append(u)
    return graph

def bfs_shortest(graph: Dict[int, List[int]], start: int) -> Dict[int, int]:
    dist = {start: 0}
    queue = deque([start])
    while queue:
        node = queue.popleft()
        for nxt in graph[node]:
            if nxt not in dist:
                dist[nxt] = dist[node] + 1
                queue.append(nxt)
    return dist

def dfs_iterative(graph: Dict[int, List[int]], start: int) -> List[int]:
    order, seen, stack = [], {start}, [start]
    while stack:
        node = stack.pop()
        order.append(node)
        for nxt in graph[node]:
            if nxt not in seen:
                seen.add(nxt)
                stack.append(nxt)
    return order

def dijkstra(graph: Dict[int, List[Tuple[int, int]]], start: int) -> Dict[int, int]:
    dist = {start: 0}
    heap = [(0, start)]
    while heap:
        d, node = heapq.heappop(heap)
        if d > dist.get(node, INF):
            continue
        for nxt, w in graph.get(node, []):
            nd = d + w
            if nd < dist.get(nxt, INF):
                dist[nxt] = nd
                heapq.heappush(heap, (nd, nxt))
    return dist

class UnionFind:
    def __init__(self, n: int):
        self.parent = list(range(n))
        self.size = [1] * n
        self.components = n

    def find(self, x: int) -> int:
        while self.parent[x] != x:
            self.parent[x] = self.parent[self.parent[x]]
            x = self.parent[x]
        return x

    def union(self, a: int, b: int) -> bool:
        ra, rb = self.find(a), self.find(b)
        if ra == rb:
            return False
        if self.size[ra] < self.size[rb]:
            ra, rb = rb, ra
        self.parent[rb] = ra
        self.size[ra] += self.size[rb]
        self.components -= 1
        return True

    def connected(self, a: int, b: int) -> bool:
        return self.find(a) == self.find(b)

def merge_intervals(intervals: List[List[int]]) -> List[List[int]]:
    if not intervals:
        return []
    intervals = sorted(intervals, key=lambda x: x[0])
    merged = [intervals[0][:]]
    for start, end in intervals[1:]:
        if start <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], end)
        else:
            merged.append([start, end])
    return merged

def gcd(a: int, b: int) -> int:
    while b:
        a, b = b, a % b
    return a

def sieve(n: int) -> List[int]:
    is_prime = [True] * (n + 1)
    is_prime[0:2] = [False, False]
    for p in range(2, int(math.isqrt(n)) + 1):
        if is_prime[p]:
            for multiple in range(p * p, n + 1, p):
                is_prime[multiple] = False
    return [i for i, ok in enumerate(is_prime) if ok]

def single_number(nums: List[int]) -> int:
    result = 0
    for x in nums:
        result ^= x
    return result

def fib_memo(n: int) -> int:
    @lru_cache(maxsize=None)
    def f(k: int) -> int:
        return k if k < 2 else f(k - 1) + f(k - 2)

    return f(n)

def climb_stairs(n: int) -> int:
    a, b = 1, 1
    for _ in range(n - 1):
        a, b = b, a + b
    return b

def coin_change(coins: List[int], amount: int) -> int:
    dp = [0] + [INF] * amount
    for target in range(1, amount + 1):
        for c in coins:
            if c <= target:
                dp[target] = min(dp[target], dp[target - c] + 1)
    return -1 if dp[amount] == INF else int(dp[amount])

def print_grid(grid: List[List]) -> None:
    for row in grid:
        print(" ".join(str(x) for x in row))
